import sqlite3
con=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True)
tabs=[r[0] for r in con.execute("select name from sqlite_master where type='table'")]
hard,soft=[],[]
for t in tabs:
    fks={fk[3] for fk in con.execute(f'PRAGMA foreign_key_list("{t}")') if fk[2]=='items'}
    if not fks: continue
    for col in con.execute(f'PRAGMA table_info("{t}")'):
        if col[1] in fks:
            (hard if col[3] else soft).append(f"{t}.{col[1]}")
print("UNWRITABLE — NOT NULL FK into empty items (%d):" % len(hard))
for x in sorted(hard): print("   ", x)
print("\nnullable, so still writable with NULL (%d):" % len(soft))
for x in sorted(soft): print("   ", x)
